var i=[{title:`Рухи стегна`,text:`Згинання стегна наближає стегно до тулуба, а розгинання відводить його назад. Суглоб також обертається всередину й назовні та рухає ногу поперек тіла чи від нього. Повсякденні рухи поєднують кілька напрямків, тож дотягування до носків уперед розповідає лише частину історії.`},{title:`Вправи, які варто спробувати`,text:`Комфортна розтяжка згиначів стегна в положенні напівстоячи на коліні досліджує розгинання, поки ви тримаєте таз під контролем. М’які обертання стегон 90/90 чи вправи на обертання сидячи тренують обертання, а бічний випад із опорою досліджує довжину та контроль привідних м’язів (внутрішня поверхня стегна). Починайте повільно і тримайтеся за опору, якщо рівновага відчувається хиткою.`},{title:`Стегна у ваших підйомах`,text:`Присідам потрібно, щоб стегна й щиколотки рухалися разом. Нахилам потрібне згинання стегон із контрольованим тулубом. У спліт-присіді одне стегно розгинається, а інше згинається. Якщо глибокий присід відчувається некомфортно, інша постава, менша глибина, опора під п’яти чи присід на стілець можуть вирішити це швидше, ніж форсована розтяжка.`},{title:`Стегна в усіх різні`,text:`Форма кульшової западини, тренувальна історія, поточна сила та переносимість суглоба: усе це впливає на вашу амплітуду. Асиметрія не є автоматично дефектом, і та сама розтяжка не належить у кожен план. Припиніть будь-яку вправу, що викликає защемлення, різкий біль у суглобі чи симптоми, що затримуються, і за потреби зверніться до лікаря чи фізіотерапевта.`},{title:`Відстеження прогресу`,text:`Робіть кілька цілеспрямованих вправ для стегон перед заняттями, де рух від цього виграє. Вимірюйте прогрес за тим, наскільки впевненими й плавними відчуваються ваші присіди, нахили та випади, а максимальну глибину розтяжки лишіть осторонь.`}];var l=[{label:`ACE 2026: рухливість і гнучкість`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`Бібліотека вправ ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:i,sources:l};export{r as default,i as sections,l as sources};